    id        INT          NOT NULL,
    plain     DATETIME(6)  NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    with_zone TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (id)
);

